using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ShadowMasteryAction", menuName = "Data/Battle/Battle Actions/Moonie/ShadowMastery Action")]
public class ShadowMasteryAction : DiceOnHandBasedPurifyAction
{
	[Header("Shadow Ritual Specifics")]
	[SerializeField]
	private DefaultEffectAction playerSelfDoomAction;

	[SerializeField]
	private OmenLogic targetToApplyEffectLogic;

	[SerializeField]
	private int multiplier;

	public DefaultEffectAction PlayerSelfDoomAction => playerSelfDoomAction;

	public int Multiplier => multiplier;

	public override void CastAmount(int amount, GameObject source)
	{
		targetToApplyEffectLogic.ActivateOmen(playerSelfDoomAction, 1, null, source);
		int purifyAmount = GetPurifyAmount(0);
		if (purifyAmount > 0)
		{
			targetToApplyEffectLogic.ActivateOmen(playerSelfDoomAction, GetDoomAmount(amount), null, source);
			targetToPurifyLogic.ActivateOmen(purifyAction, purifyAmount, null, source);
		}
		ResetVariables();
	}

	public override int GetPurifyAmount(int amount)
	{
		int num = 0;
		for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
		{
			DiceInstance diceInstanceFromHand = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i);
			if (diceInstanceFromHand.ActionFace.BattleAction is CorruptAction)
			{
				num++;
			}
			if (diceInstanceFromHand.ActionFace.EnableSecondAction && diceInstanceFromHand.ActionFace.SecondBattleAction is CorruptAction)
			{
				num++;
			}
		}
		return num * multiplier;
	}

	public int GetDoomAmount(int amount)
	{
		int num = 0;
		for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
		{
			DiceInstance diceInstanceFromHand = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i);
			if (diceInstanceFromHand.ActionFace.BattleAction is CorruptAction)
			{
				num++;
			}
			if (diceInstanceFromHand.ActionFace.EnableSecondAction && diceInstanceFromHand.ActionFace.SecondBattleAction is CorruptAction)
			{
				num++;
			}
		}
		return num * amount;
	}
}
